/* Practical field guides. These are original study aids, not a replacement for local protocols. */
const PRACTICAL={
 5:{why:'Terminology is a safety tool: a precise handoff lets the next clinician picture the patient without seeing them.',workflow:['Break an unfamiliar word into prefix, root, combining vowel, and suffix.','Translate the location using the patient’s right and left, proximal/distal, medial/lateral, and anterior/posterior.','Use only standard abbreviations in documentation; if an abbreviation could be misunderstood, write it out.','Repeat back unfamiliar language during handoff rather than guessing.'],red:['Laterality is missing from the report.','A medication or procedure abbreviation is unclear.','The same term is being used to describe two different locations.'],mistakes:['Using your own left and right instead of the patient’s.','Assuming every term has a prefix.','Inventing an abbreviation on a patient care report.'],scenario:'A patient has a wound “distal and lateral to the left knee.” Describe the location in plain language before you document it.',challenge:{prompt:'A bystander says a wound is “on the left.” You are facing the patient and cannot tell whether they mean the patient or themselves. What is the safest handoff?',options:['Document your left because that is what you see','Clarify the patient’s side and use anatomic language before documenting','Document both sides to avoid choosing','Skip laterality because the wound is visible'],right:1,why:'Clarifying laterality prevents a preventable communication error.'}},
 6:{why:'Anatomy becomes useful when it explains why a patient looks sick and which body function you must support first.',workflow:['Start with the visible problem, then connect it to the relevant structure and function.','For breathing, separate airway patency, ventilation, gas exchange, circulation, and cellular oxygen use.','Compare both sides and use landmarks to localize pain, deformity, or abnormal sounds.','Reassess after an intervention because function can change faster than structure.'],red:['Mental status changes without an obvious explanation.','Work of breathing increases or chest movement becomes asymmetric.','Skin signs and pulse suggest perfusion is worsening.'],mistakes:['Treating a normal SpO₂ as proof that ventilation is adequate.','Describing a location vaguely instead of using landmarks.','Focusing on one body system while missing a connected problem.'],scenario:'A patient has a clear airway but shallow respirations and new confusion. Explain why airway opening alone has not solved the problem.',challenge:{prompt:'A patient’s airway is open, but respirations are shallow and mental status is worsening. Which explanation best guides your next action?',options:['An open airway guarantees adequate oxygen delivery','Ventilation or perfusion may still be failing, so reassess breathing and circulation','The patient is stable because the radial pulse is present','Anatomy is unrelated to treatment decisions'],right:1,why:'Airway patency is only one link in oxygen delivery; ventilation and perfusion still need assessment.'}},
 7:{why:'Age changes the meaning of vital signs, the patient’s reserve, and how you gain cooperation.',workflow:['Observe infants and children before touching them; look at appearance, position, interaction, and work of breathing.','Use age-appropriate equipment and compare vital signs with age and baseline.','Treat increased work of breathing, poor tone, and altered behavior as early warning signs.','For older adults, ask about baseline function, medications, falls, and subtle changes.'],red:['A child becomes quiet after struggling to breathe.','Poor tone, cyanosis, altered interaction, or exhaustion.','A caregiver reports “not acting right” even when one vital sign looks normal.'],mistakes:['Forcing a frightened child flat or separating them unnecessarily.','Using adult equipment or adult expectations.','Dismissing caregiver observations.'],scenario:'A toddler is sitting upright with a caregiver and becomes quieter after several minutes of labored breathing. Treat the quietness as possible fatigue, not improvement.',challenge:{prompt:'A toddler with labored breathing becomes unusually quiet and stops crying. The respiratory rate falls. What should you assume first?',options:['The child is calming down and can wait','The child may be tiring; reassess immediately and support breathing','The caregiver has solved the problem','A lower rate is always normal in a child'],right:1,why:'A falling rate with worsening behavior can signal fatigue and impending respiratory failure.'}},
 8:{why:'Moving a patient is a clinical intervention. A rushed lift can worsen injury, expose the crew, or delay care.',workflow:['Make the scene safe and decide whether the move is emergency or planned.','Estimate patient and equipment weight; choose the correct device and enough rescuers.','Assign one leader, explain the plan, clear the path, and coordinate on a count.','Secure the patient, reassess after movement, and report any change.'],red:['Fire, traffic, violence, or another immediate hazard.','The patient cannot maintain position or has a life threat requiring access.','The planned move exceeds the team’s strength or equipment.'],mistakes:['Lifting before checking the path.','Twisting while carrying or letting one person lead without warning.','Moving a stable patient urgently when a safer planned move is available.'],scenario:'Before moving a heavy patient around a tight corner, identify the turn, doorways, equipment, and who will lead each movement.',challenge:{prompt:'A stable patient weighs about 300 lb and the route has a tight turn. What is the best first decision?',options:['Begin the lift and solve the turn as you reach it','Request adequate help or a mechanical device and plan the entire route','Ask the patient to stand regardless of dizziness','Pull the patient by the arms'],right:1,why:'The team must match the plan and equipment to the load and route before lifting.'}},
 9:{pending:true,why:'The Chapter 9 source is not available in the uploads I can access.',workflow:[],red:[],mistakes:[],scenario:'Upload the Chapter 9 audio or pages and I will build this guide from the actual material.',challenge:null},
 10:{why:'Assessment is a loop: recognize threats, intervene, reassess, and communicate what changed.',workflow:['Make the scene safe, use standard precautions, and identify the nature of illness or mechanism.','Form a general impression and check responsiveness, airway, breathing, circulation, major bleeding, and mental status.','Obtain focused history and exam only after immediate threats are addressed.','Repeat the primary assessment and vital signs after every major intervention or change.'],red:['Airway noise, inadequate chest rise, severe bleeding, altered mental status, or signs of shock.','A patient who looks better briefly and then worsens.','A vital-sign trend moving in the wrong direction.'],mistakes:['Taking a long history before treating a life threat.','Anchoring on the chief complaint.','Failing to reassess after movement or medication.'],scenario:'Use SAMPLE and OPQRST to fill gaps, but stop the interview immediately if the patient develops a new airway, breathing, or circulation threat.',challenge:{prompt:'A chest-pain patient is answering OPQRST but becomes pale, confused, and hypotensive. What should you do next?',options:['Finish OPQRST because it has already started','Stop the history, return to the primary assessment, support immediate threats, and expedite care','Ask the family for more history before touching the patient','Document the change after arrival'],right:1,why:'A new life threat always interrupts the secondary assessment.'}},
 11:{why:'Airway care is about effective air movement. Oxygen concentration cannot compensate for a patient who is not ventilating.',workflow:['Look, listen, and feel for airway patency and effective breathing; count rate and assess depth, effort, chest rise, sounds, and mental status.','Clear secretions and open the airway with the appropriate maneuver.','Choose an adjunct only when the patient and contraindications fit; confirm size and placement.','Use oxygen for adequate breathing when indicated; use BVM support for absent or inadequate breathing.','Watch chest rise and response continuously; correct the seal, position, or obstruction if ventilation fails.'],red:['Gurgling, snoring, stridor, silence with poor air movement, cyanosis, fatigue, or altered mental status.','A normal SpO₂ with a very slow or shallow respiratory pattern.','No chest rise with BVM breaths.'],mistakes:['Using a nonrebreather when the patient needs ventilation.','Overventilating or squeezing too hard.','Leaving a poor mask seal uncorrected.','Inserting an airway adjunct without checking gag reflex or contraindications.'],scenario:'If a patient has a pulse but breaths are slow and shallow, manage airway and ventilation first; do not wait for SpO₂ to fall.',challenge:{prompt:'A patient with a pulse has respirations of 5/min, shallow chest rise, and SpO₂ 97%. Which action is best?',options:['Nonrebreather alone because SpO₂ is above 94%','Open the airway and assist ventilations with a BVM and oxygen per protocol','Wait two minutes and repeat the SpO₂','Start chest compressions immediately'],right:1,why:'The patient is failing ventilation. SpO₂ may remain normal temporarily while carbon dioxide rises and air movement is inadequate.'}},
 12:{why:'Medication administration is a verification process, not a memory test.',workflow:['Confirm the patient, indication, medication, dose, route, time, expiration, and your authorized scope.','Check allergies, contraindications, relevant history, and the patient’s ability to receive the route safely.','Explain what you are doing, obtain consent when appropriate, and follow protocol or medical direction.','Reassess effect and adverse reactions; document the medication and response.'],red:['Unclear label, unknown dose, allergy, contraindication, or a patient who cannot safely swallow.','A new rash, wheeze, hypotension, or mental-status change after administration.'],mistakes:['Giving a familiar medication from memory.','Assuming a prescribed medication is automatically within EMT scope.','Documenting administration without documenting response.'],scenario:'If the label or dose cannot be verified, pause and contact medical direction rather than guessing.',challenge:{prompt:'A patient asks for help with a prescribed medication, but the label is smudged and the dose cannot be confirmed. What is safest?',options:['Give the usual dose from memory','Do not administer until it is verified under protocol or medical direction','Double-check the dose with a bystander','Give half the dose and observe'],right:1,why:'An unverified medication and dose create avoidable harm; scope and medical direction control the decision.'}},
 13:{why:'Shock is a perfusion problem that can be present before blood pressure falls.',workflow:['Look for the cause: hemorrhage, pump failure, distributive process, or obstruction.','Control external bleeding immediately and support airway and breathing.','Keep the patient warm, position according to condition and protocol, and arrange rapid transport.','Trend pulse, respirations, mental status, skin signs, capillary refill, and blood pressure.'],red:['Restlessness or confusion, cool clammy skin, weak or rapid pulse, delayed capillary refill, and worsening trends.','A patient who becomes quieter, weaker, or less responsive.','A near-normal BP paired with worsening pulse and skin signs.'],mistakes:['Waiting for hypotension.','Giving food or drink to a potentially deteriorating patient.','Treating the number instead of the patient and the cause.'],scenario:'Compare each reassessment with the last. A pulse rising from 118 to 132 while pressure falls is deterioration even if pressure is not yet very low.',challenge:{prompt:'After blood loss, a patient’s pulse rises from 118 to 132, respirations rise from 26 to 30, and BP falls from 112/74 to 104/68. What does this mean?',options:['The patient is stable because systolic BP remains above 100','Compensation may be failing; continue shock care and expedite transport','The pulse change is probably anxiety only','Give oral fluids and reassess later'],right:1,why:'The trend shows worsening perfusion. Shock treatment and transport should not wait for profound hypotension.'}},
 14:{why:'Resuscitation rewards speed, rhythm, and quality: recognize arrest, compress well, use the AED, and minimize pauses.',workflow:['Confirm unresponsiveness and abnormal breathing; activate the response and obtain an AED.','Check a pulse for no more than 10 seconds if trained. If no definite pulse, begin CPR.','Compress at the current recommended rate and depth with full recoil and minimal interruptions.','Attach the AED as soon as available, clear for analysis or shock, and resume CPR immediately when directed.','For a pulse with absent or inadequate breathing, ventilate at the current guideline rate and reassess.'],red:['Agonal gasps mistaken for normal breathing.','Long pauses for pulse checks, analysis, or equipment.','Excessive ventilation or incomplete recoil.'],mistakes:['Waiting for perfect certainty when no definite pulse is found.','Touching the patient during AED analysis.','Using a nonrebreather for a pulseless patient instead of CPR and AED.'],scenario:'During a resuscitation, say “clear” before analysis or shock, then restart compressions without an unnecessary delay.',challenge:{prompt:'The AED arrives while compressions are in progress. What action best preserves resuscitation quality?',options:['Stop all care until the pads are perfectly positioned','Attach pads while the team minimizes interruption, clear for analysis, then follow the prompt and resume CPR','Check the pulse for 30 seconds before turning it on','Remove the AED if it does not advise a shock'],right:1,why:'Early AED use matters, but pauses must be short and the device prompts must be followed.'}},
 15:{why:'A medical call can evolve quickly. The patient’s immediate physiology outranks the first label or the longest story.',workflow:['Start with scene, general impression, and primary assessment.','Use the chief complaint to guide a focused history and exam, not to close the differential prematurely.','Identify time-sensitive patterns and establish onset or last-known-well when relevant.','Communicate findings, interventions, response, and changes in a structured handoff.'],red:['New focal neurological findings, altered mental status, severe chest pain, respiratory failure, shock, or sudden deterioration.','A distracting chronic history that conflicts with a new objective finding.'],mistakes:['Anchoring on a familiar diagnosis.','Ignoring the timeline.','Failing to tell the receiving team what changed after treatment.'],scenario:'If a patient’s new facial droop is dismissed as “old dizziness,” establish baseline and last-known-well before moving on.',challenge:{prompt:'A patient says “dizziness,” but you find new facial droop and slurred speech while the spouse describes years of vertigo. What is your priority?',options:['Finish the chronic vertigo history','Treat the new focal findings as time-sensitive, establish last-known-well, and activate the appropriate pathway','Have the patient walk to test balance','Give oral fluids and reassess in 20 minutes'],right:1,why:'New objective neurological deficits demand a time-sensitive evaluation; chronic history is secondary.'}},
 16:{why:'Respiratory emergencies are decided by effort, air movement, mental status, and response—not one monitor number.',workflow:['Position for comfort and assess rate, depth, effort, chest rise, sounds, skin, mental status, and SpO₂.','Support oxygenation when indicated while watching for fatigue or worsening mental status.','If breaths are absent or inadequate, open the airway and assist ventilation with a BVM.','Reassess after every intervention; a rising SpO₂ does not cancel shallow breathing or drowsiness.'],red:['One-word speech, exhaustion, altered mental status, poor chest rise, slowing rate, cyanosis, or a suddenly quiet chest.','A patient whose saturation improves while air movement worsens.'],mistakes:['Calling reduced wheezing improvement without checking air movement.','Relying on SpO₂ alone.','Leaving a tiring patient on oxygen without preparing to ventilate.'],scenario:'A COPD patient’s SpO₂ rises from 84% to 96% but she becomes drowsy with shallow chest rise. That is worsening ventilation, not resolution.',challenge:{prompt:'A respiratory patient’s SpO₂ improves from 84% to 96%, but she becomes drowsy and chest rise is shallow. What should you conclude?',options:['The patient is cured because the saturation improved','Ventilation is deteriorating; assist ventilations and reassess immediately','Remove oxygen because the number is now normal','Begin a detailed secondary exam'],right:1,why:'Oxygen saturation can improve while ventilation fails. Mental status and chest rise are more urgent clues to inadequate ventilation.'}}
};

DATA.chapters=DATA.chapters.map(c=>({...c,practical:PRACTICAL[c.n]}));
const easyDistractors=['A definition unrelated to this problem','A step that can wait until after immediate threats','A choice that ignores the patient’s current findings'];
const easyQuestion=(c,card)=>[c.n,card[1],[card[2],...easyDistractors],0,'This level checks the core concept before you apply it to a changing patient.'];
DATA.quizLevels={};
DATA.chapters.forEach(c=>{
  const easy=DATA.cards.filter(x=>x[0]===c.n).slice(0,4).map(x=>easyQuestion(c,x));
  const apply=DATA.questions.filter(q=>q[0]===c.n);
  const challenge=c.practical?.challenge?[c.n,c.practical.challenge.prompt,c.practical.challenge.options,c.practical.challenge.right,c.practical.challenge.why]:null;
  DATA.quizLevels[c.n]={1:easy,2:apply,3:challenge?[challenge]:[]};
});
